// r764 (queue main#76): presence guard for the frozen panel fixtures.
// ---------------------------------------------------------------------------
// WHY: logs\ is gitignored, so panel-fixture-*.html / -hist.jsonl are build
// products (queue main#40, regenerated by Tools\devloop\rebuild-panel-fixtures.ps1).
// On a fresh tree the suites' fs.readFileSync threw a bare ENOENT stack and
// exited 1, which reads like "the panel broke" instead of "the fixtures were
// never built". This module answers one question -- which fixtures are missing --
// and formats the one-line fix.
//
// Two groups because the suites need different files: the history suite wants
// the prev/regress pair, the self-check suite only the bad build. Asking for
// both would make one suite fail over a file it never reads.
//
// Pure functions only: no fs, no spawn. The caller injects `exists` so this
// logic is testable without touching disk.
'use strict';

const HISTORY = [
  { path: 'logs/panel-fixture-snap.json', what: 'frozen snapshot' },
  { path: 'logs/panel-fixture-prev.html', what: 'prev build' },
  { path: 'logs/panel-fixture-prev-hist.jsonl', what: 'prev history' },
  { path: 'logs/panel-fixture-regress.html', what: 'regress build' },
  { path: 'logs/panel-fixture-regress-hist.jsonl', what: 'regress history' }
];

const SELFCHECK = [
  { path: 'logs/panel-fixture-bad.html', what: 'bad self-check build' }
];

const GROUPS = { history: HISTORY, selfcheck: SELFCHECK };

// The rebuild is PowerShell (it drives build-city-panel.ps1 with -SnapPath /
// -HistoryPath / -OutPath); the suites never spawn it -- they only name it.
const REBUILD = 'powershell -File Tools\\devloop\\rebuild-panel-fixtures.ps1';

function entriesFor(group) {
  const g = GROUPS[group];
  if (!g) throw new Error('unknown fixture group: ' + group);
  return g;
}

function missingFixtures(exists, group) {
  return entriesFor(group).filter(function (f) { return !exists(f.path); })
    .map(function (f) { return f.path; });
}

// Human lines: one per missing file with its role, then the fix.
function formatGuardMessage(missing, group) {
  const byPath = {};
  entriesFor(group).forEach(function (f) { byPath[f.path] = f.what; });
  const lines = ['FIXTURES MISSING (' + group + '): ' + missing.length +
    ' of ' + entriesFor(group).length];
  missing.forEach(function (p) {
    lines.push('  missing  ' + p + '  (' + (byPath[p] || 'unknown') + ')');
  });
  lines.push('REBUILD: ' + REBUILD);
  lines.push('  (regenerates every fixture from the CURRENT template; ~20-40 s;');
  lines.push('   -Refresh re-freezes the snapshot from world-public\\city-snapshot.json)');
  return lines;
}

// Single line for suite runners that only echo the last line of output.
function formatGuardVerdict(missing) {
  return 'RESULT pass=0 fail=0 missing=' + missing.length +
    ' :: fixtures not built; run: ' + REBUILD;
}

module.exports = {
  HISTORY: HISTORY,
  SELFCHECK: SELFCHECK,
  REBUILD: REBUILD,
  entriesFor: entriesFor,
  missingFixtures: missingFixtures,
  formatGuardMessage: formatGuardMessage,
  formatGuardVerdict: formatGuardVerdict
};